        gul = ''.join(f'<circle cx="200" cy="{ypad(t) - (9 if t == 3 else 0):.1f}" r="9" fill="{"#c0392b" if t == 0 else "#e8a093"}" stroke="#c0392b" stroke-width="2"/>' for t in range(4))
